#!/usr/bin/env python3
"""Compare actual visible-copy and end-of-audio frame counters at each rAF."""
import os,bisect,concurrent.futures,json,pathlib,sys,time,subprocess,urllib.request
kind,prefix=sys.argv[1:3];frames=next((int(x.split('=',1)[1])for x in sys.argv if x.startswith('--frames=')),5400);yield_present='--yield'in sys.argv;warmup=60
base=json.loads(pathlib.Path(os.environ.get('OU_CONTROL_RECORD','analysis/performance-control.json')).read_text())['control_url']
def req(action,**kw):
 with urllib.request.urlopen(urllib.request.Request(base,data=json.dumps(dict(action=action,**kw)).encode(),headers={'Content-Type':'application/json'}),timeout=650)as r:return json.load(r)['result']
req('screen',path=prefix+'-start.png')
req('eval',source='''(()=>{const o=orderup,g=o.runtime.graphics,a=o.runtime.audio,s=window.presentationExperiment={count:0,presents:[],presentFrames:[],completed:[],completedFrames:[],originalPresent:g.present,originalPump:a.pump,active:true,lastCount:0,lastCompleted:o.frames};g.present=function(){s.originalPresent.call(this);if(!o.runtime.inCall){s.count++;s.lastPresentAt=performance.now()}else s.nativeSwaps=(s.nativeSwaps||0)+1};if(__YIELD__)a.pump=async function(r){await r.yieldHost();return s.originalPump.call(this,r)};function capture(t){if(!s.active)return;if(s.count!==s.lastCount){s.presents.push(t);s.presentFrames.push(s.count);s.lastCount=s.count}if(o.frames!==s.lastCompleted){s.completed.push(t);s.completedFrames.push(o.frames);s.lastCompleted=o.frames}s.request=requestAnimationFrame(capture)}s.request=requestAnimationFrame(capture);return true})()'''.replace('__YIELD__','true'if yield_present else'false'))
with concurrent.futures.ThreadPoolExecutor()as pool:
 future=pool.submit(req,'measure',frames=frames,warmup=warmup,path=prefix+'.json');time.sleep(.5);req('label',text='OK',options={'timeout':10000,'after':100});subprocess.run(['python3','tools/perf_'+kind+'_mouse.py',prefix+'-mouse.json'],check=True);result=future.result()
audit=req('eval',source="(()=>{const o=orderup,g=o.runtime.graphics,a=o.runtime.audio,s=presentationExperiment;s.active=false;cancelAnimationFrame(s.request);g.present=s.originalPresent;a.pump=s.originalPump;return{native_swap_calls:s.nativeSwaps||0,presents:s.presents,presentFrames:s.presentFrames,completed:s.completed,completedFrames:s.completedFrames,presentCount:s.count}})()")
def stats(times,ids):
 times=times[warmup:];return{'minimum_frames_in_sliding_second':min(i-bisect.bisect_left(times,t-1000)for i,t in enumerate(times)if t-times[0]>=1000),'skipped_frame_presentations':sum(max(0,b-a-1)for a,b in zip(ids,ids[1:]))}
audit['summary']={'actual_presentations':stats(audit['presents'],audit['presentFrames']),'end_of_audio_counter':stats(audit['completed'],audit['completedFrames']),'post_present_message_yield':yield_present,'no_additional_game_updates':audit['presentCount']==result['work']['samples']+warmup,'presentations':audit['presentCount'],'measured_updates':result['work']['samples']+warmup};pathlib.Path(prefix+'-presentation.json').write_text(json.dumps(audit));end=req('screen',path=prefix+'-result.png');print(json.dumps({k:result[k]for k in ['fps','minimum_frames_in_sliding_second','work','audio_gaps','graphics_errors','error']},indent=2),flush=True);print({'presentation':audit['summary'],'result_text':[x['text']for x in end['text']]},flush=True)
